<?php
declare(strict_types=1);$pageTitle='My Notebook';require_once __DIR__.'/../includes/header.php';require_once __DIR__.'/_helpers.php';require_once __DIR__.'/_church_engagement.php';require_permission('member.profile.view');ce_install($conn);$mid=current_member_id();
try{if($_SERVER['REQUEST_METHOD']==='POST'){ce_check_csrf();$action=(string)($_POST['action']??'save');if($action==='delete'){$id=(int)($_POST['id']??0);$st=$conn->prepare("DELETE FROM member_notebook WHERE id=? AND member_id=?");$st->bind_param('ii',$id,$mid);$st->execute();$st->close();ce_redirect('notebook.php','Notebook entry deleted.');}$id=(int)($_POST['id']??0);$title=trim((string)($_POST['title']??''));$note=trim((string)($_POST['note_text']??''));$date=(string)($_POST['note_date']??date('Y-m-d'));if($title===''||$note==='')throw new RuntimeException('Enter a title and note.');if($id>0){$st=$conn->prepare("UPDATE member_notebook SET title=?,note_text=?,note_date=? WHERE id=? AND member_id=?");$st->bind_param('sssii',$title,$note,$date,$id,$mid);}else{$st=$conn->prepare("INSERT INTO member_notebook(member_id,title,note_text,note_date) VALUES(?,?,?,?)");$st->bind_param('isss',$mid,$title,$note,$date);}$st->execute();$st->close();ce_redirect('notebook.php','Notebook entry saved.');}}catch(Throwable $e){$_SESSION['ce_flash']=['message'=>$e->getMessage(),'type'=>'danger'];}
$editId=(int)($_GET['edit']??0);$edit=$editId?mp_row($conn,"SELECT * FROM member_notebook WHERE id=? AND member_id=?",'ii',[$editId,$mid]):null;$rows=mp_rows($conn,"SELECT * FROM member_notebook WHERE member_id=? ORDER BY note_date DESC,id DESC",'i',[$mid]);include __DIR__.'/../includes/sidebar.php';?><div class="main-content"><?php include __DIR__.'/../includes/topbar.php';?><div class="content-wrapper"><?php ce_flash();?><div class="card"><div class="card-header"><h3>My Private Notebook</h3></div><div class="card-body"><form method="post" class="ce-form"><input type="hidden" name="csrf_token" value="<?=mp_h(ce_csrf())?>"><input type="hidden" name="id" value="<?=(int)($edit['id']??0)?>"><div class="row2"><div><label>Title</label><input class="form-control" name="title" required value="<?=mp_h($edit['title']??'')?>"></div><div><label>Date</label><input class="form-control" type="date" name="note_date" value="<?=mp_h($edit['note_date']??date('Y-m-d'))?>"></div></div><div><label>Notes</label><textarea class="form-control" name="note_text" required><?=mp_h($edit['note_text']??'')?></textarea></div><button class="btn btn-primary"><i class="fas fa-save"></i> Save Note</button></form></div></div><div class="ce-grid" style="margin-top:18px"><?php foreach($rows as $r):?><article class="ce-card"><div class="ce-meta"><span><?=mp_date($r['note_date'])?></span></div><h4><?=mp_h($r['title'])?></h4><div class="ce-note"><?=nl2br(mp_h($r['note_text']))?></div><div class="ce-actions"><a class="btn btn-sm btn-secondary" href="?edit=<?=(int)$r['id']?>">Edit</a><form method="post" onsubmit="return confirm('Delete this note?')"><input type="hidden" name="csrf_token" value="<?=mp_h(ce_csrf())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><button class="btn btn-sm btn-danger">Delete</button></form></div></article><?php endforeach;?></div></div></div><?php mp_standard_styles();ce_styles();require_once __DIR__.'/../includes/footer.php';?>
